fn get_min_val(a: &Vec<i8>) -> i8 {
    *a.iter().min().unwrap()  // unwrap is safe because array is non-empty
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    *a.iter().max().unwrap()  // unwrap is safe because array is non-empty
}

fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    // Validate q is in range [0, 100]
    assert!(q >= 0 && q <= 100, "Quantile must be between 0 and 100");
    
    // Handle edge cases for q = 0 and q = 100
    if q == 0 {
        return get_min_val(&a);
    }
    if q == 100 {
        return get_max_val(&a);
    }
    
    // Sort the array
    a.sort();
    
    // Calculate the index for the quantile
    // Using linear interpolation between sorted values
    let n = a.len();
    let position = (q as f64 / 100.0) * (n - 1) as f64;
    
    // Get the lower and upper indices
    let lower_idx = position.floor() as usize;
    let upper_idx = position.ceil() as usize;
    
    // If lower and upper are the same, return that element
    if lower_idx == upper_idx {
        return a[lower_idx];
    }
    
    // Linear interpolation between the two values
    let lower_val = a[lower_idx] as f64;
    let upper_val = a[upper_idx] as f64;
    let fraction = position - lower_idx as f64;
    
    let result = lower_val + fraction * (upper_val - lower_val);
    
    // Round to nearest i8 (since we need to return i8)
    result.round() as i8
}